import { readFileSync } from "node:fs";
import { join } from "node:path";

import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

// Generated by `npm run gen` from ../docs/api/*.json; not committed.
import integratorApi from "./docs/integrator-api/sidebar";
import internalApi from "./docs/internal-api/sidebar";

// Each use-case guide sits under the BRD module that owns the functions it
// describes. Titles and order come from the generated document, so they
// cannot drift from the code's manifests.
const GUIDES_BY_MODULE: Record<string, string[]> = {
  consent_lifecycle: ["consent-flow"],
  user_dashboard: ["rights"],
  grievance: ["grievances"],
};

type ModuleEntry = { name: string; title: string };
const modules: ModuleEntry[] = JSON.parse(readFileSync(join(__dirname, ".specs", "integrator.json"), "utf8"))[
  "x-modules"
];
const unplaced = Object.keys(GUIDES_BY_MODULE).filter((name) => !modules.some((module) => module.name === name));
if (unplaced.length) {
  throw new Error(`sidebars.ts: no such module in the integrator document: ${unplaced.join(", ")}`);
}

const sidebars: SidebarsConfig = {
  guides: [
    "intro",
    {
      type: "category",
      label: "Core concepts",
      collapsed: false,
      items: ["authentication", "tenancy", "errors"],
    },
    ...modules
      .filter((module) => GUIDES_BY_MODULE[module.name])
      .map((module) => ({
        type: "category" as const,
        label: module.title,
        collapsed: false,
        items: GUIDES_BY_MODULE[module.name],
      })),
  ],
  integratorApi,
  internalApi,
};

export default sidebars;
